import java.util.*;

public class Main {
    List<Integer> insertionSortList(List<Integer> values) {
        List<Integer> result = new ArrayList<>();
        for (int v : values) {                                                     // take each value one at a time, exactly like card-sorting by hand
            int i = result.size();
            while (i > 0 && result.get(i - 1) > v) i--;                                // shift larger values right to make room
            result.add(i, v);
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        List<Integer> values = Arrays.asList(4, 2, 1, 3);
        System.out.println(solution.insertionSortList(values));
    }
}

