#include <bits/stdc++.h>
using namespace std;

vector<int> insertionSortList(vector<int>& values) {
    vector<int> result;
    for (int v : values) {                                                        // take each value one at a time, exactly like card-sorting by hand
        int i = result.size();
        while (i > 0 && result[i - 1] > v) i--;                                       // shift larger values right to make room
        result.insert(result.begin() + i, v);
    }
    return result;
}

int main() {
    vector<int> values = {4, 2, 1, 3};
    vector<int> result = insertionSortList(values);
    for (int v : result) cout << v << " ";
    cout << endl;
    return 0;
}

