import java.util.*;

public class Main {
    ListNode insertionSortList(ListNode head) {
        ListNode dummy = new ListNode(0);                                           // sorted result begins empty, anchored by a dummy head
        ListNode curr = head;
        while (curr != null) {
            ListNode next = curr.next;                                                 // save curr's original next BEFORE it gets re-linked
            ListNode prev = dummy;
            while (prev.next != null && prev.next.val < curr.val) {                       // walk the sorted portion to find curr's correct spot
                prev = prev.next;
            }
            curr.next = prev.next;                                                        // insert curr right there
            prev.next = curr;
            curr = next;                                                                  // continue with the ORIGINAL next node from the unsorted portion
        }
        return dummy.next;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(4, new ListNode(2, new ListNode(1, new ListNode(3))));
        ListNode result = solution.insertionSortList(head);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

