#include <bits/stdc++.h>
using namespace std;

ListNode* insertionSortList(ListNode* head) {
    ListNode dummy(0);                                                              // sorted result begins empty, anchored by a dummy head
    ListNode* curr = head;
    while (curr) {
        ListNode* next = curr->next;                                                   // save curr's original next BEFORE it gets re-linked
        ListNode* prev = &dummy;
        while (prev->next && prev->next->val < curr->val) {                               // walk the sorted portion to find curr's correct spot
            prev = prev->next;
        }
        curr->next = prev->next;                                                          // insert curr right there
        prev->next = curr;
        curr = next;                                                                      // continue with the ORIGINAL next node from the unsorted portion
    }
    return dummy.next;
}

int main() {
    ListNode* head = new ListNode(4, new ListNode(2, new ListNode(1, new ListNode(3))));
    ListNode* result = insertionSortList(head);
    while (result) { cout << result->val << " "; result = result->next; }
    cout << endl;
    return 0;
}
